/* Lightweight sound synthesis and visual feedback. No downloads or external SDKs. */
const GeoFX=(()=>{
 let audio=null,enabled=true,volume=.45,burstTimer=null,toastTimer=null,combo=0;
 const motion=()=>!window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;
 function unlock(){if(!enabled)return null;try{const C=window.AudioContext||window.webkitAudioContext;if(!C)return null;audio??=new C();if(audio.state==='suspended')audio.resume().catch(()=>{});return audio}catch{return null}}
 const melodies={tap:[[440,0,.045],[660,.025,.06]],focus:[[740,0,.08]],correct:[[523,0,.13],[659,.09,.14],[784,.19,.2]],wrong:[[330,0,.13],[247,.11,.18]],start:[[392,0,.12],[523,.12,.12],[659,.24,.15]],complete:[[523,0,.15],[659,.12,.15],[784,.24,.15],[1047,.4,.32]],perfect:[[523,0,.12],[659,.1,.12],[784,.2,.14],[1047,.35,.2],[784,.55,.15],[1047,.7,.4]],timeout:[[440,0,.12],[440,.2,.12],[330,.4,.22]]};
 function play(type){if(!enabled||volume===0||document.hidden)return;const c=unlock();if(!c||c.state!=='running')return;try{const now=c.currentTime;for(const [freq,delay,duration]of melodies[type]||melodies.tap){const o=c.createOscillator(),g=c.createGain();o.type=type==='wrong'?'triangle':'sine';o.frequency.setValueAtTime(freq,now+delay);g.gain.setValueAtTime(.0001,now+delay);g.gain.exponentialRampToValueAtTime(.12*volume,now+delay+.012);g.gain.exponentialRampToValueAtTime(.0001,now+delay+duration);o.connect(g);g.connect(c.destination);o.start(now+delay);o.stop(now+delay+duration+.02);o.onended=()=>{o.disconnect();g.disconnect()}}}catch{}}
 function setEnabled(on){enabled=!!on;if(!enabled&&audio?.state==='running')audio.suspend().catch(()=>{});else if(enabled)unlock()}
 function setVolume(v){volume=Math.max(0,Math.min(1,Number(v)||0))}
 function toast(message,kind='good'){const t=document.getElementById('fxToast');if(!t)return;t.textContent=message;t.className='fx-toast visible '+kind;clearTimeout(toastTimer);toastTimer=setTimeout(()=>{t.className='fx-toast'},2300)}
 function burst(big=false){if(!motion())return;const layer=document.getElementById('fxParticles');if(!layer)return;clearTimeout(burstTimer);layer.replaceChildren();for(let i=0;i<(big?55:20);i++){const p=document.createElement('i');p.className='fx-particle';p.style.setProperty('--x',`${15+Math.random()*70}vw`);p.style.setProperty('--dx',`${(Math.random()-.5)*270}px`);p.style.setProperty('--delay',`${Math.random()*.28}s`);p.style.setProperty('--spin',`${Math.random()*900-450}deg`);p.style.setProperty('--color',['#54d9b6','#ffcc74','#78b8ff','#f69ebc'][i%4]);layer.appendChild(p)}burstTimer=setTimeout(()=>layer.replaceChildren(),2400)}
 function animate(el,cls){if(!el||!motion())return;el.classList.remove(cls);void el.offsetWidth;el.classList.add(cls);setTimeout(()=>el.classList.remove(cls),700)}
 function feedback(ok,target){combo=ok?combo+1:0;animate(target,ok?'fx-right':'fx-shake');if(ok){burst();toast(combo>=3?`🔥 ${combo}次連對！繼續保持！`:'✨ 答對！地理感又強咗！')}else toast('🧭 唔緊要，睇清解說再記一次。','retry')}
 function complete(perfect=false){play(perfect?'perfect':'complete');burst(true);toast(perfect?'🏆 完美滿分！你係地理達人！':'🎉 完成挑戰！又向前一步！')}
 function focusMap(prefix,i){document.querySelectorAll('.map-point.is-active,.map-answer.is-active,.map-links line.is-active').forEach(el=>el.classList.remove('is-active'));for(const id of [prefix+'point'+i,prefix+'box'+i,prefix+'line'+i])document.getElementById(id)?.classList.add('is-active');play('focus')}
 function pointResult(prefix,i,ok){const p=document.getElementById(prefix+'point'+i);p?.classList.add(ok?'correct':'wrong');animate(document.getElementById(prefix+'box'+i),ok?'fx-right':'fx-shake')}
 function resetCombo(){combo=0}
 function install(){document.addEventListener('pointerdown',unlock,{capture:true});document.addEventListener('keydown',unlock,{capture:true});document.addEventListener('click',e=>{const b=e.target.closest?.('button');if(!b||b.disabled||b.id==='sound'||b.classList.contains('map-point'))return;const action=b.getAttribute('onclick')||'';if(/answerPractice|markShort|checkMap|gradeExam|beginExam/.test(action))return;play('tap');if(motion()){const dot=document.createElement('span');dot.className='fx-ripple';b.appendChild(dot);setTimeout(()=>dot.remove(),500)}});const app=document.getElementById('app');if(app&&typeof MutationObserver!=='undefined'){const observer=new MutationObserver(()=>{if(motion()){app.classList.remove('fx-enter');void app.offsetWidth;app.classList.add('fx-enter')}});observer.observe(app,{childList:true})}}
 return{unlock,play,setEnabled,setVolume,feedback,complete,focusMap,pointResult,toast,resetCombo,install};
})();
